from taf.gnb.oam.coam.cu.interfaces.cuoam25r2 import CUOAM25R2
from taf.gnb.oam.coam.cu.utilities.use_m2m_parser import enforce_use_m2m_type


class CUOAM25R3(CUOAM25R2):
    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value, should_activate=True, timeout=300):
        return self.asm_licensed.perform_parameter_recommissioning(dist_name=dist_name,
                                                                   parameter=parameter,
                                                                   operation=operation,
                                                                   value=value,
                                                                   should_activate=should_activate,
                                                                   timeout=timeout,
                                                                   nidd_info=self.get_nidd())

    def perform_object_recommissioning(self, dist_name, parameter, operation, should_activate=True, timeout=300):
        return self.asm_licensed.perform_object_recommissioning(dist_name=dist_name,
                                                                parameter=parameter,
                                                                operation=operation,
                                                                should_activate=should_activate,
                                                                timeout=timeout,
                                                                nidd_info=self.get_nidd())

    @enforce_use_m2m_type
    def get_scf(self, timeout=30, include_runtime_data=False, include_auto_config_data=True, use_m2m=True):
        if use_m2m:
            return self.cm_licensed.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                             timeout=timeout,
                                                             include_auto_config_data=include_auto_config_data)
        else:
            return self.cm.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                    timeout=timeout,
                                                    include_auto_config_data=include_auto_config_data)

    def start_diagnostic_check(self, allow_service_impact=False, wait_for_completion=False, timeout=300):
        return self.asm_licensed.start_diagnostic_check(allow_service_impact=allow_service_impact,
                                                        wait_for_completion=wait_for_completion,
                                                        timeout=timeout)

    def get_diagnostic_check_status(self, operation_id, timeout=30):
        return self.asm_licensed.get_diagnostic_check_status(operation_id=operation_id, timeout=timeout)

    def get_diagnostic_check_reports(self, timeout=30):
        return self.asm_licensed.get_diagnostic_check_reports(timeout=timeout)

    def get_vnf_checkpoints(self, timeout=30):
        return self.asm_v1.get_vnf_checkpoints(timeout=timeout)

    def start_customized_diagnostic_check(self, vnf_checkpoint_ids, wait_for_completion=False,
                                          timeout=300):
        return self.asm_v1.start_customized_diagnostic_check(vnf_checkpoint_ids=vnf_checkpoint_ids,
                                                             wait_for_completion=wait_for_completion,
                                                             timeout=timeout)

    def get_customized_diagnostic_check_status(self, operation_id, timeout=30):
        return self.asm_v1.get_customized_diagnostic_check_status(operation_id=operation_id, timeout=timeout)

    @staticmethod
    def _get_complex_parameter_value(parameter_info, parameter_structure):
        """
        This function is used to retrieve value of complex parameters. It can be different depneding on the structure
        of the `parameter_structure`.
        Return value is a:
        - string, for example "7" when `parameter_structure` is in form of, for example: ["guAMI", "0", "mnc"]
        - list of dictionaries in object, when `parameter_structure` is in form of, for example: ["guAMI", "0"].
          Example return:
            [
                {
                    'value': '2',
                    'state': 'unchanged',
                    'name': 'amfPointer'
                },
                {
                    'value': '2',
                    'state': 'unchanged',
                    'name': 'amfRegionID'
                },
                {
                    'value': '7',
                    'state': 'unchanged',
                    'name': 'mnc'
                }
            ]
        - list of lists of objects, when `parameter_structure` is in form of, for example: ["guAMI"]. Example return:
            [
                [
                    {
                        'value': '2',
                        'state': 'unchanged',
                        'name': 'amfPointer'
                    },
                    {
                        'value': '2',
                        'state': 'unchanged',
                        'name': 'amfRegionID'
                    },
                    {
                        'value': '7',
                        'state': 'unchanged',
                        'name': 'mnc'
                    }
                ],
                [
                    {
                        'value': '2',
                        'state': 'unchanged',
                        'name': 'amfPointer'
                    },
                    {
                        'value': '2',
                        'state': 'unchanged',
                        'name': 'amfRegionID'
                    },
                    {
                        'value': '8',
                        'state': 'unchanged',
                        'name': 'mnc'
                    }
                ]
            ]
        """
        structure_length = len(parameter_structure)

        if structure_length == 1:
            return parameter_info['complex_parameter']

        elif structure_length == 2:
            complex_parameter_list_id = parameter_structure[1]
            return parameter_info['complex_parameter'][int(complex_parameter_list_id)]

        elif structure_length == 3:
            complex_parameter_list_id = parameter_structure[1]
            parameter_name = parameter_structure[-1]
            complex_values = parameter_info['complex_parameter'][int(complex_parameter_list_id)]

            for parameter in complex_values:
                if parameter['name'] == parameter_name:
                    return parameter['value']


    def _get_parameter_depending_on_type(self, parameter_structure, mo_dn, parameters):
        for param in parameters['items']:
            if param['distname'] == mo_dn and param['parameter_name'] == parameter_structure[0]:
                parameter_info = param['parameter']
                parameter_type = parameter_info['parameter_type']

                if parameter_type == 'simple':
                    return parameter_info['simple_parameter']['value']

                if parameter_type == 'simple_list':
                    return parameter_info['simple_list_parameter']['value']

                if parameter_type == 'complex':
                    return self._get_complex_parameter_value(parameter_info, parameter_structure)

    @staticmethod
    def _get_parameter_name(para_name):
        """
        In `search_parameter_of_current_plan` parameter name can be given in three formats:
        1. <parameter_name>
        2. <main_parameter_name>/<complex_parameter_list_id>
        3. <main_parameter_name>/<complex_parameter_list_id>/<sub_parameter_name>
        This function will return the parameter name and the structure of the parameter name in form of a list.
        For example:
        1. <parameter_name> will return ('<parameter_name>', ['<parameter_name>'])
        2. <main_parameter_name>/<complex_parameter_list_id> will return
           ('<main_parameter_name>', ['<main_parameter_name>', '<complex_parameter_list_id>'])
        3. <main_parameter_name>/<complex_parameter_list_id>/<sub_parameter_name> will return
           ('<main_parameter_name>', ['<main_parameter_name>', '<complex_parameter_list_id>', '<sub_parameter_name>'])
        """
        parameter_structure = para_name.split('/')
        parameter_name = parameter_structure[0] if len(parameter_structure)==2 else parameter_structure[-1]
        return parameter_name, parameter_structure

    def search_parameter_of_current_plan(self, para_name, mo_dn):
        parameter_name, parameter_structure = self._get_parameter_name(para_name)
        parameters = self.search_parameters_of_current_plan(parameter_name)
        param_value = self._get_parameter_depending_on_type(parameter_structure, mo_dn, parameters)
        if param_value:
            return param_value
        raise KeyError(f"Parameter: {para_name} not found in {mo_dn} in the current plan")

    @enforce_use_m2m_type
    def get_local_snapshot(self, directory, request_timeout, operation_timeout, use_m2m=True, compressed=True, sdl_components=None,
                           include_sdl_history_recordings=False, coverage='full', filter_regx=None):
        if use_m2m:
            return self.asm_licensed.get_local_snapshot(directory=directory,
                                                        request_timeout=request_timeout,
                                                        operation_timeout=operation_timeout,
                                                        compressed=compressed,
                                                        coverage=coverage,
                                                        filter_regx=filter_regx)
        else:
            return self.asm_v1.get_local_snapshot(directory=directory,
                                                  request_timeout=request_timeout,
                                                  operation_timeout=operation_timeout,
                                                  compressed=compressed,
                                                  sdl_components=sdl_components,
                                                  include_sdl_history_recordings=include_sdl_history_recordings,
                                                  coverage=coverage,
                                                  filter_regx=filter_regx)

    @enforce_use_m2m_type
    def trigger_local_snapshot(self, request_timeout=30, use_m2m=True, sdl_components=None, include_sdl_history_recordings=False, coverage='full',
                               filter_regx=None):
        if use_m2m:
            return self.asm_licensed.trigger_local_snapshot(request_timeout=request_timeout,
                                                            coverage=coverage,
                                                            filter_regx=filter_regx)
        else:
            return self.asm_v1.trigger_local_snapshot(request_timeout=request_timeout,
                                                      sdl_components=sdl_components,
                                                      include_sdl_history_recordings=include_sdl_history_recordings,
                                                      coverage=coverage,
                                                      filter_regx=filter_regx)

    def start_ip_reachability_test(self, timeout=30):
        return self.trs.start_ip_reachability_test(timeout=timeout)

    def get_ip_reachability_test_status(self, operation_id, timeout=30):
        return self.trs.get_ip_reachability_test_status(operation_id=operation_id, timeout=timeout)
